#include <iostream>
#include <string>
using namespace std;

int calcularDano(int ataque, int defesa) {
    int dano = ataque - defesa;
    if (dano < 1) {
        return 1;
    }
    return dano;
}

void mostrarGolpe(string atacante, string alvo, int dano) {
