#include <iostream>
using namespace std;

void receberDano(int& vida, int dano) {
    vida -= dano;
    if (vida < 0) {
        vida = 0;
    }
}

void trocar(int& a, int& b) {
    int aux = a;
    a = b;
    b = aux;
}

int main() {
    int vida = 50;
    receberDano(vida, 18);
    cout << "Vida: " << vida << endl;
    receberDano(vida, 40);
    cout << "Vida: " << vida << endl;

    int mao = 12;
    int mochila = 20;
    trocar(mao, mochila);
    cout << "Na mão: " << mao << " | Na mochila: " << mochila << endl;
    return 0;
}

