#include <iostream>
using namespace std;

int limitar(int valor, int minimo = 0, int maximo = 100) {
    if (valor < minimo) {
        return minimo;
    }
    if (valor > maximo) {
        return maximo;
    }
    return valor;
}

double limitar(double valor, double minimo = 0.0, double maximo = 1.0) {
    if (valor < minimo) {
        return minimo;
    }
    if (valor > maximo) {
        return maximo;
    }
    return valor;
}

int main() {
    cout << limitar(150) << endl;
    cout << limitar(7, 1, 5) << endl;
    cout << limitar(0.25) << endl;
    cout << limitar(1.5) << endl;
    return 0;
}

