#include <iostream>
using namespace std;

int emSegundos(int horas, int minutos, int segundos);
void mostrarTempo(int totalSegundos);
bool passouDoLimite(int totalSegundos, int limiteMinutos = 120);

int main() {
    int total = emSegundos(1, 45, 30) + emSegundos(0, 50, 45);
    cout << "Tempo total: ";
    mostrarTempo(total);
    cout << "Passou de 2 horas? " << (passouDoLimite(total) ? "sim" : "não") << endl;
    cout << "Passou de 3 horas? " << (passouDoLimite(total, 180) ? "sim" : "não") << endl;
    return 0;
}

int emSegundos(int horas, int minutos, int segundos) {
    return horas * 3600 + minutos * 60 + segundos;
}

void mostrarTempo(int totalSegundos) {
    int horas = totalSegundos / 3600;
    int minutos = totalSegundos % 3600 / 60;
    int segundos = totalSegundos % 60;
    cout << horas << "h " << minutos << "min " << segundos << "s" << endl;
}

bool passouDoLimite(int totalSegundos, int limiteMinutos) {
    return totalSegundos > limiteMinutos * 60;
}

