#include <iostream>
using namespace std;

int blocos(int andares) {
    if (andares == 0) {
        return 0;
    }
    return andares + blocos(andares - 1);
}

int somaDigitos(int n) {
    if (n < 10) {
        return n;
    }
    return n % 10 + somaDigitos(n / 10);
}

