#include <iostream>
using namespace std;

// ===== Biblioteca de matemática =====
int mdc(int a, int b);
int mmc(int a, int b);
bool ehPrimo(int n);
void simplificar(int& numerador, int& denominador);
int potencia(int base, int expoente = 2);

int main() {
    cout << "mdc(48, 18) = " << mdc(48, 18) << endl;
    cout << "mmc(4, 6) = " << mmc(4, 6) << endl;
    cout << "17 é primo? " << (ehPrimo(17) ? "sim" : "não") << endl;
    int num = 8;
    int den = 12;
    simplificar(num, den);
    cout << "8/12 = " << num << "/" << den << endl;
    cout << "potencia(5) = " << potencia(5) << endl;
    cout << "potencia(2, 10) = " << potencia(2, 10) << endl;
    return 0;
}

// ===== Definições =====

int mdc(int a, int b) {
    if (b == 0) {
        return a;
    }
    return mdc(b, a % b);
}

int mmc(int a, int b) {
    return a / mdc(a, b) * b;
}

bool ehPrimo(int n) {
    if (n < 2) {
        return false;
    }
    for (int d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            return false;
        }
    }
    return true;
}

void simplificar(int& numerador, int& denominador) {
    int divisor = mdc(numerador, denominador);
    numerador /= divisor;
    denominador /= divisor;
}

int potencia(int base, int expoente) {
    int resultado = 1;
    for (int i = 0; i < expoente; i++) {
        resultado *= base;
    }
    return resultado;
}
